import{_ as l,c as s,o as r,j as i,af as h,a as n,t}from"./chunks/framework.W5ZyBR1w.js";const f=JSON.parse('{"title":"标识符","description":"本章主要讲述 MSST-Net 的主体类型与标识符体系。","frontmatter":{"title":"标识符","description":"本章主要讲述 MSST-Net 的主体类型与标识符体系。"},"headers":[],"relativePath":"connect/basics/identifiers.md","filePath":"connect/basics/identifiers.md"}'),d={name:"connect/basics/identifiers.md"},p={id:"frontmatter-title",tabindex:"-1"};function o(e,a,c,b,g,k){return r(),s("div",null,[i("h1",p,[n(t(e.$frontmatter.title)+" ",1),a[0]||(a[0]=i("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":"Permalink to “{{ $frontmatter.title }}”"},"​",-1))]),i("p",null,t(e.$frontmatter.description),1),a[1]||(a[1]=h('<h2 id="主体类型" tabindex="-1">主体类型 <a class="header-anchor" href="#主体类型" aria-label="Permalink to “主体类型”">​</a></h2><p>在 MSST-Net 中，<strong>主体</strong>是网络中的基本标识单位。</p><p>目前，MSST-Net 支持以下主体类型：</p><ul><li>用户</li><li>设备</li></ul><p>每个主体都具有独立的标识符，用于识别、管理和访问控制。</p><hr><h2 id="用户" tabindex="-1">用户 <a class="header-anchor" href="#用户" aria-label="Permalink to “用户”">​</a></h2><p><strong>用户</strong>是一类基本主体，用于标识同一用户关联的所有设备。</p><p>对于<strong>免认证用户</strong>，系统会自动创建一个仅与当前设备关联的本地用户主体，因此该用户通常只关联当前设备。</p><p>对于<strong>认证用户</strong>，登录到同一账号的所有设备都会关联到同一用户主体。</p><p>用户主体主要用于统一管理多个设备的身份关系。</p><hr><h2 id="设备" tabindex="-1">设备 <a class="header-anchor" href="#设备" aria-label="Permalink to “设备”">​</a></h2><p><strong>设备</strong>是一类基本主体，用于标识唯一的客户端实例。</p><p>每个接入到 MSST-Net 的客户端实例都会对应一个独立的设备主体。</p><p>当前版本中，MSST-Net 的访问控制主要以<strong>设备</strong>作为最小控制单位。</p><hr><h2 id="标识符体系" tabindex="-1">标识符体系 <a class="header-anchor" href="#标识符体系" aria-label="Permalink to “标识符体系”">​</a></h2><p>每个主体都具有以下三类标识符：</p><ul><li>ID（唯一标识符）</li><li>助记符（可读标识符）</li><li>显示名称（展示标识符）</li></ul><p>不同类型的标识符适用于不同场景。</p><hr><h2 id="id" tabindex="-1">ID <a class="header-anchor" href="#id" aria-label="Permalink to “ID”">​</a></h2><p><strong>ID</strong> 是主体的唯一标识符。</p><p>每个主体的 ID 在创建后即固定，不可修改。</p><p>所有其他标识符都建立在 ID 的基础上。</p><h3 id="格式规则" tabindex="-1">格式规则 <a class="header-anchor" href="#格式规则" aria-label="Permalink to “格式规则”">​</a></h3><p>用户 ID：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>usr-{8位十六进制}</span></span></code></pre></div><p>设备 ID：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>usr-{8位十六进制}</span></span></code></pre></div><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h3><p>用户 ID：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>usr-1a2b3c4d</span></span></code></pre></div><p>设备 ID：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dev-a7f29b3e</span></span></code></pre></div><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to “特性”">​</a></h3><ul><li>全局唯一</li><li>不可修改</li><li>可用于规则引用</li><li>推荐用于精确标识主体</li></ul><h2 id="助记符" tabindex="-1">助记符 <a class="header-anchor" href="#助记符" aria-label="Permalink to “助记符”">​</a></h2><p><strong>助记符</strong>是主体的人类可读标识符。</p><p>助记符主要用于简化引用、生成可读名称以及构建规则。</p><p>助记符允许用户修改，但其唯一性取决于主体类型与作用域。</p><h3 id="助记符的分类" tabindex="-1">助记符的分类 <a class="header-anchor" href="#助记符的分类" aria-label="Permalink to “助记符的分类”">​</a></h3><p>MSST-Net 当前支持以下助记符类型：</p><ul><li>用户助记符</li><li>设备助记符</li><li>组合助记符</li></ul><h3 id="用户助记符" tabindex="-1">用户助记符 <a class="header-anchor" href="#用户助记符" aria-label="Permalink to “用户助记符”">​</a></h3><p>用户助记符用于标识用户主体。</p><p>用户助记符在全局范围内唯一。</p><h4 id="示例-1" tabindex="-1">示例 <a class="header-anchor" href="#示例-1" aria-label="Permalink to “示例”">​</a></h4><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>abjust</span></span></code></pre></div><h4 id="特性-1" tabindex="-1">特性 <a class="header-anchor" href="#特性-1" aria-label="Permalink to “特性”">​</a></h4><ul><li>全局唯一</li><li>可修改</li><li>可用于规则引用</li><li>适用于标识用户</li></ul><h3 id="设备助记符" tabindex="-1">设备助记符 <a class="header-anchor" href="#设备助记符" aria-label="Permalink to “设备助记符”">​</a></h3><p>设备助记符用于标识设备主体。</p><p>设备助记符仅在同一用户作用域内保证唯一。</p><p>这意味着：</p><ul><li>不同用户可以使用相同设备助记符</li><li>同一用户下出现重复设备助记符将触发冲突处理</li></ul><h4 id="示例-2" tabindex="-1">示例 <a class="header-anchor" href="#示例-2" aria-label="Permalink to “示例”">​</a></h4><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>archlinux</span></span></code></pre></div><h4 id="特性-2" tabindex="-1">特性 <a class="header-anchor" href="#特性-2" aria-label="Permalink to “特性”">​</a></h4><ul><li>用户作用域内唯一</li><li>可修改</li><li>可用于规则引用</li><li>适用于用户内部引用设备</li></ul><h2 id="显示名称" tabindex="-1">显示名称 <a class="header-anchor" href="#显示名称" aria-label="Permalink to “显示名称”">​</a></h2><p><strong>显示名称</strong>是主体对外展示的名称。</p><p>显示名称主要用于界面展示和用户识别。</p><p>显示名称允许重复，不保证唯一。</p><h3 id="特性-3" tabindex="-1">特性 <a class="header-anchor" href="#特性-3" aria-label="Permalink to “特性”">​</a></h3><ul><li>不保证唯一</li><li>可修改</li><li>不可用于规则引用</li><li>用于界面展示</li></ul><h3 id="示例-3" tabindex="-1">示例 <a class="header-anchor" href="#示例-3" aria-label="Permalink to “示例”">​</a></h3><p>设备显示名称：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Abjust 的电脑</span></span></code></pre></div><h2 id="标识符对比" tabindex="-1">标识符对比 <a class="header-anchor" href="#标识符对比" aria-label="Permalink to “标识符对比”">​</a></h2><table tabindex="0"><thead><tr><th>标识符</th><th>唯一性</th><th>可修改</th><th>可用于规则</th><th>主要用途</th></tr></thead><tbody><tr><td>ID</td><td>是</td><td>否</td><td>是</td><td>精确标识</td></tr><tr><td>助记符</td><td>否（自动处理冲突）</td><td>是</td><td>是</td><td>简化引用</td></tr><tr><td>显示名称</td><td>否</td><td>是</td><td>否</td><td>对外展示</td></tr></tbody></table>',72))])}const x=l(d,[["render",o]]);export{f as __pageData,x as default};
